import unittest
from interval import contains
class IntervalTests(unittest.TestCase):
    def test_lower_and_interior(self):
        for value in (2, 3): self.assertTrue(contains(value, 2, 4))
    def test_upper_and_singleton(self):
        self.assertFalse(contains(4, 2, 4))
        self.assertFalse(contains(2, 2, 2))
    def test_outside(self):
        for value in (1, 5): self.assertFalse(contains(value, 2, 4))
